<?php
namespace App\Models; use App\Models\Concerns\InvalidatesFaqs; use Illuminate\Database\Eloquent\{Builder,Factories\HasFactory,Model}; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class Faq extends Model { use HasFactory,InvalidatesFaqs; protected $fillable=['faq_group_id','question','answer','status','is_featured','display_order','published_at','scheduled_for','archived_at','created_by','updated_by']; protected function casts():array{return ['is_featured'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];} public function group():BelongsTo{return $this->belongsTo(FaqGroup::class,'faq_group_id');} public function homepageItems():HasMany{return $this->hasMany(HomepageItem::class);} public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));} public function isPubliclyVisible():bool{return $this->archived_at===null&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}
